    const to = this.generateTo().trim();
    if ((from && !DATE.test(from)) || (to && !DATE.test(to))) {
      this.generateError.set('Type a from and a to date as YYYY-MM-DD.');
      return;
    }
    if (from && to && to < from) {
      this.generateError.set('The to-date must not be before the from-date.');
      return;
