          data-testid="period-generate-fy-year"
          inputmode="numeric"
          placeholder="YYYY"
          [value]="generateFyYear()"
          (input)="generateFyYear.set(value($event)); generateError.set(null)"
        />
        <button type="button" data-testid="period-generate-fy" (click)="generateFiscalYear()">
